var treeWalker = document.createTreeWalker(
    document.getElementById("content"),
    NodeFilter.SHOW_ELEMENT,
    { acceptNode: function(node) { return ["P", "H1", "H2", "H3", "H4", "H5", "UL", "OL"].includes(node.tagName)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_SKIP; } }
);

// create a new div
var div2 = document.createElement("div");


while (treeWalker.nextNode()) {
    var node = treeWalker.currentNode;
    // construct a node of the same type and append it to
    // the new div
    var newNode = document.createElement(node.tagName);
    newNode.innerText = node.innerText;
    div2.appendChild(newNode);
}
